    async def list_yubikey_otp_tokens(
        self,
        *,
        after: typing.Optional[str] = None,
        expand: typing.Optional[str] = None,
        filter: typing.Optional[ListYubikeyOtpTokensRequestFilter] = None,
        for_download: typing.Optional[bool] = None,
        limit: typing.Optional[int] = None,
        sort_by: typing.Optional[ListYubikeyOtpTokensRequestSortBy] = None,
        sort_order: typing.Optional[ListYubikeyOtpTokensRequestSortOrder] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> typing.List[UserFactorYubikeyOtpToken]:
        """
        Lists all YubiKey OTP tokens

        Parameters
        ----------
        after : typing.Optional[str]
            Specifies the pagination cursor for the next page of tokens

        expand : typing.Optional[str]
            Embeds the [user](/openapi/okta-management/management/tags/user) resource if the YubiKey token is assigned to a user and `expand` is set to `user`

        filter : typing.Optional[ListYubikeyOtpTokensRequestFilter]
            The expression used to filter tokens

        for_download : typing.Optional[bool]
            Returns tokens in a CSV to download instead of in the response. When you use this query parameter, the `limit` default changes to 1000.

        limit : typing.Optional[int]
            Specifies the number of results per page

        sort_by : typing.Optional[ListYubikeyOtpTokensRequestSortBy]
            The value of how the tokens are sorted

        sort_order : typing.Optional[ListYubikeyOtpTokensRequestSortOrder]
            Specifies the sort order, either `ASC` or `DESC`

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        typing.List[UserFactorYubikeyOtpToken]
            Success
        """
        _response = await self._raw_client.list_yubikey_otp_tokens(
            after=after,
            expand=expand,
            filter=filter,
            for_download=for_download,
            limit=limit,
            sort_by=sort_by,
            sort_order=sort_order,
            request_options=request_options,
        )
        return _response.data

    async def resend_enroll_factor(
        self,
        user_id: str,
        factor_id: str,
        *,
        request: ResendUserFactor,
        template_id: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ResendUserFactor:
        """
        Resends an `sms`, `call`, or `email` factor challenge as part of an enrollment flow.

        For `call` and `sms` factors, Okta enforces a rate limit of one OTP challenge per device every 30 seconds. You can configure your `sms` and `call` factors to use a third-party telephony provider. See the [Telephony inline hook reference](https://developer.okta.com/docs/reference/telephony-hook/). Okta alternates between SMS providers with every resend request to ensure delivery of SMS and Call OTPs across different carriers.

        > **Note:** Resend operations aren't allowed after a factor exceeds the activation rate limit. See [Activate a factor](./#tag/UserFactor/operation/activateFactor).

        Parameters
        ----------
        user_id : str
            ID of an existing Okta user

        factor_id : str
            ID of an existing user factor

        request : ResendUserFactor

        template_id : typing.Optional[str]
            ID of an existing custom SMS template. See the [SMS Templates API](../Template). This parameter is only used by `sms` factors.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ResendUserFactor
            Success
        """
        _response = await self._raw_client.resend_enroll_factor(
            user_id, factor_id, request=request, template_id=template_id, request_options=request_options
        )
        return _response.data

    async def unenroll_factor(
        self,
        user_id: str,
        factor_id: str,
        *,
        remove_recovery_enrollment: typing.Optional[bool] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> None:
        """
        Unenrolls an existing factor for the specified user. You can't unenroll a factor from a deactivated user. Unenrolling a factor allows the user to enroll a new factor.

        > **Note:** If you unenroll the `push` or the `signed_nonce` factors, Okta also unenrolls any other `totp`, `signed_nonce`, or Okta Verify `push` factors associated with the user.

        Parameters
        ----------
        user_id : str
            ID of an existing Okta user

        factor_id : str
            ID of an existing user factor

        remove_recovery_enrollment : typing.Optional[bool]
            If `true`, removes the phone number as both a recovery method and a factor. This parameter is only used for the `sms` and `call` factors.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        None
        """
        _response = await self._raw_client.unenroll_factor(
            user_id, factor_id, remove_recovery_enrollment=remove_recovery_enrollment, request_options=request_options
        )
        return _response.data

