    async def verify_factor(
        self,
        user_id: str,
        factor_id: str,
        *,
        request: UserFactorVerifyRequest,
        template_id: typing.Optional[str] = None,
        token_lifetime_seconds: typing.Optional[int] = None,
        accept_language: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> UserFactorVerifyResponse:
        """
        Verifies an OTP for a factor. Some factors (`call`, `email`, `push`, `sms`, `u2f`, and `webauthn`) must first issue a challenge before you can verify the factor. Do this by making a request without a body. After a challenge is issued, make another request to verify the factor.

        > **Notes:**
        > - You can send standard push challenges or number matching push challenges to Okta Verify `push` factor enrollments. Use a [request body](https://developer.okta.com/docs/api/openapi/okta-management/management/userfactor/verifyfactor!path=2/useNumberMatchingChallenge&t=request) for number matching push challenges.
        > - To verify a `push` factor, use the **poll** link returned when you issue the challenge. See [Retrieve a factor transaction status](/openapi/okta-management/management/tags/userfactor/other/getfactortransactionstatus).

        Parameters
        ----------
        user_id : str
            ID of an existing Okta user

        factor_id : str
            ID of an existing user factor

        request : UserFactorVerifyRequest

        template_id : typing.Optional[str]
            ID of an existing custom SMS template. See the [SMS Templates API](../Template). This parameter is only used by `sms` factors.

        token_lifetime_seconds : typing.Optional[int]
            Defines how long the token remains valid

        accept_language : typing.Optional[str]
            An ISO 639-1 two-letter language code that defines a localized message to send. This parameter is only used by `sms` factors. If a localized message doesn't exist or the `templateId` is incorrect, the default template is used instead.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        UserFactorVerifyResponse
            Success
        """
        _response = await self._raw_client.verify_factor(
            user_id,
            factor_id,
            request=request,
            template_id=template_id,
            token_lifetime_seconds=token_lifetime_seconds,
            accept_language=accept_language,
            request_options=request_options,
        )
        return _response.data
